(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.015+t*0.2)*20 + Math.cos(y*0.02-t*0.15)*15;
  const w1y = Math.cos(y*0.018-t*0.22)*20 + Math.sin(x*0.012+t*0.28)*15;
  const wx = x + w1x + Math.sin(w1y*0.03+t*0.5)*8;
  const wy = y + w1y + Math.cos(w1x*0.03-t*0.4)*8;
  const sx = wx + Math.sin(wy*0.01+t*0.1)*5;
  const sy = wy + Math.cos(wx*0.01-t*0.12)*5;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,1.2,0.9],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,2.5,1.1],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,3.8,0.8],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,5.0,1.2],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,6.2,0.95],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+2)*60,0.11,2.1,1.8,1.05],
    [400+Math.cos(t*0.55+4)*60,200+Math.sin(t*0.75+1)*50,0.085,1.8,4.5,0.85]
  ];
  let aS=0,iS=0,hS=0;
  for(const[sX,sY,f,sp,ph,amp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp+ph)*amp;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+ph+1.5)*amp;
    hS+=Math.sin(d*f*0.4-t*sp*0.3+ph*2)*amp*0.5;
  }
  const act=aS/8,inh=iS/8,harm=hS/8;
  const bg1=Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1);
  const bg2=Math.sin((sx+sy)*0.12+t*2.5)+Math.sin((sx-sy)*0.1-t*2);
  const bg3=Math.sin(sx*0.08-t*0.5)*Math.cos(sy*0.06+t*0.7);
  const bg=bg1/2+bg2*0.2+bg3*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const sp1=Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2);
  const sp2=Math.sin(dist*0.03+ang*5+t*0.8)*Math.cos(dist*0.06-ang*2-t*1.8);
  const spiral=(sp1+sp2)*0.3;
  const raw=act-inh*0.7+bg*0.3+spiral;
  const r1=Math.tanh(raw*2.2),r2=Math.tanh((raw+r1*0.5+harm*0.4)*2.0);
  const reaction=r1*0.6+r2*0.4;
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const cell2=Math.tanh((Math.cos(sx*0.12-t)*Math.sin(sy*0.13+t*0.5)+Math.sin(sx*0.08+sy*0.08)*0.3)*1.2)*0.2;
  const detail=Math.sin(sx*0.3+reaction*2)*Math.sin(sy*0.3-reaction*1.5)*0.15;
  const pulse=0.95+Math.sin(t*1.5)*0.05;
  const blend=(reaction*0.6+cell*0.2+cell2*0.1+detail)*pulse;
  const v=blend*0.5+0.5;
  const pal=[[6,12,52],[12,45,85],[18,90,115],[25,140,135],[80,175,120],[180,190,70],[220,170,55],[215,115,60],[185,65,65],[130,35,70],[70,20,65],[25,15,55],[6,12,52]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const sf=f*f*(3-2*f);
  const lum=0.75+Math.sin(reaction*Math.PI)*0.25;
  const eS=Math.abs(reaction),edge=eS>0.6?1.0+(eS-0.6)*0.5:1.0;
  const hShift=Math.sin(harm*2)*0.05;
  return[
    Math.min(255,Math.max(0,(pal[i][0]+(pal[i+1][0]-pal[i][0])*sf+hShift*30)*lum*edge))|0,
    Math.min(255,Math.max(0,(pal[i][1]+(pal[i+1][1]-pal[i][1])*sf+hShift*15)*lum*edge))|0,
    Math.min(255,Math.max(0,(pal[i][2]+(pal[i+1][2]-pal[i][2])*sf-hShift*20)*lum*edge))|0
  ];
}
